def fees_into_school_currency(apps, schema_editor):
    """Requote every Naira application fee in the school's own currency.

    Most partners charged a flat 200,000 Naira. The fee is now shown in the
    school's currency, so each one is converted once at the rate in the
    Exchange rates table and rounded up to a whole unit. A school already
    quoting in its own currency, such as UCAM at 150 euros, is left alone. A
    currency with no rate on file is left in Naira rather than guessed.

    On the production database the converted fees were then set from the live
    rate on 15 October 2026 (200,000 Naira = 135 euros = 210 Canadian dollars),
    because the table's rates were out of date. Staff can change any fee in the
    admin.
    """
    Institution = apps.get_model("catalog", "Institution")
    OriginCountry = apps.get_model("catalog", "OriginCountry")
    for school in Institution.objects.all():
        fee_currency = (school.application_fee_currency or "").upper()
        own = (school.currency or "").upper()
        if not fee_currency:
            school.application_fee_currency = own
            school.save(update_fields=["application_fee_currency"])
            continue
        if fee_currency != "NGN" or own in ("", "NGN") or school.application_fee <= 0:
            continue
        rate_row = OriginCountry.objects.filter(currency__iexact=own).first()
        if rate_row is None or not rate_row.ngn_per_unit:
            continue
        converted = Decimal(math.ceil(Decimal(school.application_fee) / Decimal(rate_row.ngn_per_unit)))
        school.application_fee = converted
        school.application_fee_currency = own
        school.save(update_fields=["application_fee", "application_fee_currency"])


